CREATE OR REPLACE TABLE accounts (
    account_id BIGINT NOT NULL PRIMARY KEY,
    created_at TIMESTAMP NOT NULL,
    company_name VARCHAR NOT NULL,
    email_domain VARCHAR,
    industry VARCHAR,
    company_size_band VARCHAR,
    country VARCHAR,
    billing_currency VARCHAR NOT NULL,
    timezone VARCHAR,
    signup_source VARCHAR,
    utm_source VARCHAR,
    utm_medium VARCHAR,
    utm_campaign VARCHAR,
    acquisition_motion VARCHAR NOT NULL,
    lead_id BIGINT,
    owner_user_id BIGINT,
    sso_enabled BOOLEAN NOT NULL,
    lifecycle_stage VARCHAR NOT NULL,
    first_paid_at TIMESTAMP,
    churned_at TIMESTAMP
);
COMMENT ON TABLE accounts IS 'Every team workspace that signed up. Free and paid accounts alike. Grain: one row per workspace (team) account.';
COMMENT ON COLUMN accounts.account_id IS 'Primary key.';
COMMENT ON COLUMN accounts.created_at IS 'Signup time (UTC).';
COMMENT ON COLUMN accounts.company_name IS 'Company/team name as typed by the owner.';
COMMENT ON COLUMN accounts.email_domain IS 'Owner''s email domain; NULL for personal webmail.';
COMMENT ON COLUMN accounts.industry IS 'Self-reported industry; often blank.';
COMMENT ON COLUMN accounts.company_size_band IS 'Self-reported company size.';
COMMENT ON COLUMN accounts.country IS 'ISO-3166 alpha-2 country code.';
COMMENT ON COLUMN accounts.billing_currency IS 'Currency the account is invoiced in.';
COMMENT ON COLUMN accounts.timezone IS 'Account IANA timezone.';
COMMENT ON COLUMN accounts.signup_source IS 'Raw acquisition label captured at signup; not normalized.';
COMMENT ON COLUMN accounts.utm_source IS 'UTM source at signup, if any.';
COMMENT ON COLUMN accounts.utm_medium IS 'UTM medium at signup, if any.';
COMMENT ON COLUMN accounts.utm_campaign IS 'UTM campaign at signup, if any.';
COMMENT ON COLUMN accounts.acquisition_motion IS 'How the account was acquired.';
COMMENT ON COLUMN accounts.lead_id IS 'Lead record for sales-assisted accounts.';
COMMENT ON COLUMN accounts.owner_user_id IS 'User who created the account.';
COMMENT ON COLUMN accounts.sso_enabled IS 'SAML/SSO turned on (Business plan feature).';
COMMENT ON COLUMN accounts.lifecycle_stage IS 'State as of snapshot date.';
COMMENT ON COLUMN accounts.first_paid_at IS 'First successful paid charge; NULL if never paid.';
COMMENT ON COLUMN accounts.churned_at IS 'When paid subscription ended; NULL if not churned.';

