);
COMMENT ON TABLE subscriptions IS 'A paid subscription (current state). Free usage has no subscription row. Change history lives in plan_changes. Grain: one row per paid subscription lifecycle.';
COMMENT ON COLUMN subscriptions.subscription_id IS 'Primary key.';
COMMENT ON COLUMN subscriptions.account_id IS 'Owning account.';
COMMENT ON COLUMN subscriptions.plan IS 'Current plan.';
COMMENT ON COLUMN subscriptions.billing_interval IS 'Billing cadence.';
COMMENT ON COLUMN subscriptions.seats IS 'Seats currently purchased.';
