COMMENT ON COLUMN subscriptions.status IS 'Subscription state.';
COMMENT ON COLUMN subscriptions.started_at IS 'Subscription start (UTC).';
COMMENT ON COLUMN subscriptions.current_period_start IS 'Start of the current billing period.';
COMMENT ON COLUMN subscriptions.current_period_end IS 'End of the current billing period.';
COMMENT ON COLUMN subscriptions.canceled_at IS 'Cancellation time, if canceled.';
