COMMENT ON COLUMN _truth.true_user_segment.user_id IS 'User.';
COMMENT ON COLUMN _truth.true_user_segment.account_id IS 'Account.';
COMMENT ON COLUMN _truth.true_user_segment.latent_engagement IS 'Latent engagement score driving event rates (0-1).';
COMMENT ON COLUMN _truth.true_user_segment.true_segment IS 'Archetype.';
COMMENT ON COLUMN _truth.true_user_segment.will_activate IS 'Generated to hit activation within 7 days.';
COMMENT ON COLUMN _truth.true_user_segment.aha_invited_3d IS 'Generated to invite a teammate within 3 days.';
COMMENT ON COLUMN _truth.true_user_segment.retained_12w IS 'Generated 12-week retention outcome.';

CREATE OR REPLACE TABLE _truth.true_experiment_effect (
    effect_id BIGINT NOT NULL PRIMARY KEY,
    experiment_id BIGINT NOT NULL,
    platform VARCHAR NOT NULL,
    week_since_start INTEGER NOT NULL,
    true_effect_pp DOUBLE,
    effect_shape VARCHAR,
    note VARCHAR
);
COMMENT ON TABLE _truth.true_experiment_effect IS 'True causal effect injected into each experiment. Grain: one row per experiment x platform x week.';
COMMENT ON COLUMN _truth.true_experiment_effect.effect_id IS 'Primary key.';
COMMENT ON COLUMN _truth.true_experiment_effect.experiment_id IS 'Experiment.';
COMMENT ON COLUMN _truth.true_experiment_effect.platform IS 'Platform slice; ''all'' for overall.';
COMMENT ON COLUMN _truth.true_experiment_effect.week_since_start IS '0-based week of the test.';
COMMENT ON COLUMN _truth.true_experiment_effect.true_effect_pp IS 'True lift on the primary metric, percentage points.';
COMMENT ON COLUMN _truth.true_experiment_effect.effect_shape IS 'constant | decaying | negative_on_slice';
COMMENT ON COLUMN _truth.true_experiment_effect.note IS 'Plain-English description.';

CREATE OR REPLACE TABLE _truth.answer_key (
    problem_id VARCHAR NOT NULL PRIMARY KEY,
    category VARCHAR NOT NULL,
    title VARCHAR NOT NULL,
    description VARCHAR,
    affected_tables VARCHAR,
    affected_row_count BIGINT,
    affected_arr_usd DECIMAL(12,2),
    naive_metric VARCHAR,
    naive_value DOUBLE,
    true_value DOUBLE,
    detection_hint VARCHAR,
    correct_fix VARCHAR
);
COMMENT ON TABLE _truth.answer_key IS 'The grader''s sheet: what was planted, how big, how to find and fix it. Grain: one row per planted problem.';
COMMENT ON COLUMN _truth.answer_key.problem_id IS 'B1..B7, P1..P5, G1..G4.';
COMMENT ON COLUMN _truth.answer_key.category IS 'billing | product | growth';
COMMENT ON COLUMN _truth.answer_key.title IS 'Short name.';
COMMENT ON COLUMN _truth.answer_key.description IS 'What was planted.';
COMMENT ON COLUMN _truth.answer_key.affected_tables IS 'Comma-separated tables.';
COMMENT ON COLUMN _truth.answer_key.affected_row_count IS 'Rows/accounts/users affected.';
COMMENT ON COLUMN _truth.answer_key.affected_arr_usd IS 'ARR impact where applicable.';
COMMENT ON COLUMN _truth.answer_key.naive_metric IS 'Metric an unaware analyst would report.';
COMMENT ON COLUMN _truth.answer_key.naive_value IS 'Its (wrong) value.';
COMMENT ON COLUMN _truth.answer_key.true_value IS 'Corrected value.';
COMMENT ON COLUMN _truth.answer_key.detection_hint IS 'How a good analyst would find it.';
COMMENT ON COLUMN _truth.answer_key.correct_fix IS 'How to correct for it.';

CREATE OR REPLACE TABLE _truth.planted_rows (
    problem_id VARCHAR NOT NULL,
    table_name VARCHAR NOT NULL,
    pk_value VARCHAR NOT NULL,
    role VARCHAR,
    PRIMARY KEY (problem_id, table_name, pk_value)
);
COMMENT ON TABLE _truth.planted_rows IS 'Row-level flags so every planted problem can be verified exactly. Grain: one row per affected record.';
COMMENT ON COLUMN _truth.planted_rows.problem_id IS 'Problem code.';
COMMENT ON COLUMN _truth.planted_rows.table_name IS 'Affected table.';
COMMENT ON COLUMN _truth.planted_rows.pk_value IS 'Primary key value of the affected row (as text).';
COMMENT ON COLUMN _truth.planted_rows.role IS 'e.g. ''duplicate'', ''original'', ''affected''.';
